#include <stdio.h>

int main() {
    int score = 95;
    char grade;
    if (score >= 90) {
        grade = 'A';
    } else if (score >= 80) {
        grade = 'B';
    } else {
        grade = 'C';
    }
    printf("%c\n", grade);
    return 0;
}
